//! Test backend: a synthetic picture generated by ffmpeg. Used on non-Windows systems and with RECORA_MOCK=1,
//! so the whole pipeline (segments, audio, muxing, integrity check) can be tested without a screen.
use super::{ActiveCapture, CaptureSpec, VideoStats};
use crate::ffmpeg;
use anyhow::Result;
use std::io::Write;
use std::path::Path;
use std::process::{Child, Stdio};
use std::time::Instant;

pub struct Mock {
    child: Child,
    first: Instant,
}

pub fn start(spec: &CaptureSpec, out: &Path) -> Result<Box<dyn ActiveCapture>> {
    let child = ffmpeg::cmd()
        .args(["-hide_banner", "-loglevel", "error", "-y", "-readrate", "1", "-readrate_initial_burst", "0", "-f", "lavfi", "-i"])
        .arg(format!("testsrc2=size=1280x720:rate={}", spec.fps.max(10)))
        .args(["-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", "-movflags", "+frag_keyframe+empty_moov"])
        .arg(out)
        .stdin(Stdio::piped())
        .spawn()?;
    Ok(Box::new(Mock { child, first: Instant::now() }))
}

impl ActiveCapture for Mock {
    fn first_frame(&self) -> Option<Instant> {
        Some(self.first)
    }
    fn stop(mut self: Box<Self>) -> Result<VideoStats> {
        if let Some(mut s) = self.child.stdin.take() {
            let _ = s.write_all(b"q");
        }
        let _ = self.child.wait();
        Ok(VideoStats { frames: 0 })
    }
}
